from pathlib import Path
import re

def one(s,p,r,n,flags=0):
    x,c=re.subn(p,r,s,1,flags=flags)
    if c!=1: raise SystemExit(f'{n}:{c}')
    return x

# HTML
p=Path('v4/index.html');s=p.read_text()
s=one(s,r'<div class="titleline">.*?</div>','<div class="titleline"><input id="title" class="title" placeholder="강의 제목"><span id="inputBadge" class="badge">✏️ Pencil · 👆 손가락 이동</span><label class="viewselect">동시보기 <select id="viewCount" class="tool"><option value="1">1쪽</option><option value="2">2쪽</option><option value="3">3쪽</option><option value="4">4쪽</option></select></label><button id="layoutToggle" class="tool layout-toggle">코멘트 ↓</button></div>','title')
s=one(s,r'<aside class="notes">.*?</aside>','''<aside class="notes"><div class="nhead"><div><small style="color:#6b7280;font-weight:800">PAGE NOTE</small><h2><span id="pLabel">1</span>p.</h2></div></div><div class="tags"><button class="tag exam" data-tag="[시험] ">시험</button><button class="tag important" data-tag="[중요] ">중요</button><button class="tag prof" data-tag="[교수설명] ">교수설명</button><button class="tag question" data-tag="[질문] ">질문</button><button id="time" class="tag">시간</button></div><textarea id="editor" class="editor" placeholder="이 페이지에 대한 코멘트를 입력하세요."></textarea><div class="meta"><span id="chars">0자</span><span>코멘트·필기 자동저장</span></div><section class="transcriptbox"><div class="transcripthead"><div><b>🎙 실시간 전사</b><small>코멘트와 별도로 저장됨</small></div><button id="mic" class="btn micbtn">🎤 시작</button></div><textarea id="transcript" class="transcript" placeholder="음성 전사 내용이 이곳에 별도로 쌓입니다."></textarea><div class="meta"><span id="transcriptChars">0자</span><span>페이지별 자동저장</span></div></section><div class="pinsbox"><b>📌 이 페이지 코멘트 핀</b><div id="pinList" class="pinlist"></div></div><div class="exports"><button id="docx">Word<br><small>A4 4쪽 배치</small></button><button id="printBtn">PDF<br><small>A4 4쪽 배치</small></button><button id="md">Markdown<br><small>코멘트+전사</small></button><button id="json">JSON<br><small>전체 백업</small></button></div></aside>''','aside',re.S)
s=s.replace('</main>\n<div id="toast"','</main>\n<div id="pinPopover" class="pinpopover hidden"><textarea id="pinText" placeholder="이 위치에 짧은 코멘트"></textarea><div class="pinactions"><button id="pinCancel" class="tool">취소</button><button id="pinSave" class="btn primary">저장</button></div></div>\n<div id="toast"',1)
p.write_text(s)

# CSS
