if 'V4 feature pack' not in s:s+='''\n/* V4 feature pack */\n.viewselect{display:inline-flex;align-items:center;gap:5px;font-size:11px;color:var(--muted)}.transcriptbox{border:1px solid #c7d2fe;border-radius:14px;background:#f8faff;padding:10px;display:grid;gap:8px}.transcripthead{display:flex;align-items:center;justify-content:space-between;gap:8px}.transcripthead>div{display:grid}.transcripthead small{font-size:10px;color:var(--muted)}.micbtn{min-height:34px;font-size:11px}.micbtn.listening{background:#fee2e2}.transcript{width:100%;min-height:140px;max-height:260px;resize:vertical;border:1px solid #dbeafe;border-radius:11px;background:#fff;padding:10px}.pinpopover{position:fixed;z-index:120;width:min(280px,calc(100vw - 24px));padding:10px;background:#fff;border:1px solid #f59e0b;border-radius:14px;box-shadow:0 14px 44px #11182738}.pinpopover textarea{width:100%;height:86px;resize:none;border:1px solid var(--border);border-radius:10px;padding:9px}.pinactions{display:flex;justify-content:flex-end;gap:7px;margin-top:8px}.stageInner.multi{display:grid;grid-template-columns:repeat(var(--grid-cols,2),minmax(0,1fr));gap:12px;align-items:start;justify-items:center;width:100%;min-width:100%}.previewCard{position:relative;width:100%;border:2px solid transparent;border-radius:10px;padding:5px;background:#cfd4dc;display:flex;justify-content:center}.previewCard img{display:block;max-width:100%;object-fit:contain;background:#fff}.previewPageNo{position:absolute;left:8px;top:8px;background:#111827d9;color:#fff;font-size:10px;font-weight:800;padding:3px 7px;border-radius:999px}\n'''
