s=s.replace("if(!d.objectStoreNames.contains(AS)){const s=d.createObjectStore(AS,{keyPath:'key'});s.createIndex('projectId','projectId')}","if(!d.objectStoreNames.contains(AS)){const s=d.createObjectStore(AS,{keyPath:'key'});s.createIndex('projectId','projectId')}if(!d.objectStoreNames.contains(TS)){const s=d.createObjectStore(TS,{keyPath:'key'});s.createIndex('projectId','projectId')}",1)
