s=one(s,r'function fitScale\(viewport\)\{.*?\}',"function fitScale(viewport){const cols=viewCount===1?1:2,rows=viewCount<=2?1:2,gap=viewCount===1?0:12;const w=Math.max(180,(E.stage.clientWidth-36-gap*(cols-1))/cols),h=Math.max(180,(E.stage.clientHeight-36-gap*(rows-1))/rows);return Math.min(w/viewport.width,h/viewport.height,2.2)}",'fit')
