anchor='function pagePointFromClient'
fn="async function renderMultiPreviews(){E.stageInner.querySelectorAll('.previewCard').forEach(x=>x.remove());E.stageInner.classList.toggle('multi',viewCount>1);E.stageInner.style.setProperty('--grid-cols',viewCount===1?'1':'2');if(viewCount<=1||!pdfDoc)return;for(let i=1;i<viewCount;i++){const p=currentPage+i;if(p>pdfDoc.numPages)break;const b=document.createElement('button');b.className='previewCard';b.type='button';const l=document.createElement('span');l.className='previewPageNo';l.textContent=`${p}p.`;b.appendChild(l);const c=await composePageImage(p,.9),im=document.createElement('img');im.src=c.toDataURL('image/jpeg',.82);b.appendChild(im);b.onclick=()=>goPage(p);E.stageInner.appendChild(b)}}\n"
